/**
 * Add or remove funds (audited)
 *
 * For gifts and corrections. Positive amounts add funds (only while the user has an active plan), negative remove them. Idempotent per `idempotencyKey`.
 */
export const adminLedgerControllerAdjust = <ThrowOnError extends boolean = false>(options: Options<AdminLedgerControllerAdjustData, ThrowOnError>): RequestResult<AdminLedgerControllerAdjustResponses, AdminLedgerControllerAdjustErrors, ThrowOnError> => (options.client ?? client).post<AdminLedgerControllerAdjustResponses, AdminLedgerControllerAdjustErrors, ThrowOnError>({
    security: [{ scheme: 'bearer', type: 'http' }],
    url: '/api/v1/admin/users/{id}/balance/adjustments',
    ...options,
    headers: {
        'Content-Type': 'application/json',
        ...options.headers
    }
});

/**
 * Record a payment received outside the app (audited)
 *
 * Credits the amount as a `purchase`, only while the user has an active plan. Idempotent per `paymentReference`: recording the same payment again returns the original entry.
 */
export const adminLedgerControllerRecordPurchase = <ThrowOnError extends boolean = false>(options: Options<AdminLedgerControllerRecordPurchaseData, ThrowOnError>): RequestResult<AdminLedgerControllerRecordPurchaseResponses, AdminLedgerControllerRecordPurchaseErrors, ThrowOnError> => (options.client ?? client).post<AdminLedgerControllerRecordPurchaseResponses, AdminLedgerControllerRecordPurchaseErrors, ThrowOnError>({
    security: [{ scheme: 'bearer', type: 'http' }],
    url: '/api/v1/admin/users/{id}/balance/purchases',
    ...options,
    headers: {
        'Content-Type': 'application/json',
        ...options.headers
    }
});

